import{_t as e,it as t,n,rt as r}from"./chunks/framework.CEeTaPkX.js";var i=JSON.parse(`{"title":"Recording and memory","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/recording.md","filePath":"architecture/recording.md","lastUpdated":1792141151000}`),a={name:`architecture/recording.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="recording-and-memory" tabindex="-1">Recording and memory <a class="header-anchor" href="#recording-and-memory" aria-label="Permalink to “Recording and memory”">​</a></h1><p>Caret keeps operational state, trajectory evidence and supervisor memory for different purposes. Similar names do not mean interchangeable formats.</p><h2 id="storage-map" tabindex="-1">Storage map <a class="header-anchor" href="#storage-map" aria-label="Permalink to “Storage map”">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Contents</th><th>Primary reader</th></tr></thead><tbody><tr><td><code>agent.sqlite</code></td><td>Pi conversations, documents and execution history</td><td>Pi Durable harness</td></tr><tr><td><code>vault/threads/</code></td><td>Request/turn records, tools and timing spans</td><td>Diagnostics and trace tooling</td></tr><tr><td><code>vault/episodes/YYYY-MM-DD/</code></td><td>Schema-lite action-step JSONL</td><td>Record validator and analysis</td></tr><tr><td><code>vault/tasks/</code></td><td>Schema-lite task summaries</td><td>Analysis and task joins</td></tr><tr><td><code>vault/blobs/</code></td><td>Content-addressed snapshots and screenshots</td><td>Step record references</td></tr><tr><td><code>vault/artifacts/&lt;trace&gt;/</code></td><td>Task screenshot artifacts</td><td>Task result consumers</td></tr><tr><td><code>vault/steps/</code> and <code>vault/media/</code></td><td>Separate capture-steps/VL format</td><td>Existing VL export tools</td></tr><tr><td>Letta memfs <code>memory/</code></td><td>Persona, workflows, routing and episode summaries</td><td>Supervisor memory tools</td></tr></tbody></table><p>Paths are defaults relative to the checkout except Letta&#39;s separate memory repository. Vault data is private and ignored by Git. Letta&#39;s Markdown <code>episodes/</code> summaries are not the schema-lite JSONL episodes.</p><h2 id="from-action-to-record" tabindex="-1">From action to record <a class="header-anchor" href="#from-action-to-record" aria-label="Permalink to “From action to record”">​</a></h2><p>The first v2 <code>act</code> allocates episode and recording-task IDs. The recorder snapshots <code>/ax/state</code>, resolves semantic target descriptions, lifts each executed action into schema-lite vocabulary, and records the post-action state and ranked delta. Intermediate actions use a settle delay (150 ms by default); the last action&#39;s post-state follows expectation settling.</p><table tabindex="0"><thead><tr><th>Pi action</th><th>Schema-lite action</th><th>Meaning</th></tr></thead><tbody><tr><td><code>open_app</code></td><td><code>open_app</code></td><td>Native app launch/focus</td></tr><tr><td><code>menu</code>, <code>focus_window</code>, <code>press</code></td><td><code>invoke</code></td><td>Menu invocation, raise or accessibility activation</td></tr><tr><td><code>click</code></td><td><code>focus_field</code>, <code>invoke</code>, or <code>click_xy</code></td><td>Depends on described target role and click form</td></tr><tr><td><code>set_value</code>, <code>type</code></td><td><code>insert_text</code></td><td>Replace or type text; execution tier differs</td></tr><tr><td><code>key</code></td><td><code>press_key</code></td><td>Key plus modifiers</td></tr><tr><td><code>scroll</code></td><td><code>scroll</code></td><td>Scroll deltas</td></tr><tr><td><code>wait</code>, <code>verify</code></td><td>No action record</td><td>Checks rather than mutations</td></tr></tbody></table><p><code>action.source_action</code> retains the original Pi action. Step outcomes are <code>ok</code>, <code>no_change</code>, or <code>error</code>; these differ from task statuses. Delta entries are capped at 50 with <code>delta_truncated</code> recording the dropped count. Snapshots are content-addressed, so repeated content can share blobs.</p><h2 id="a-schema-is-not-a-populated-learning-pipeline" tabindex="-1">A schema is not a populated learning pipeline <a class="header-anchor" href="#a-schema-is-not-a-populated-learning-pipeline" aria-label="Permalink to “A schema is not a populated learning pipeline”">​</a></h2><p>The task record writer currently emits empty predicate and correction arrays, null intent labels, null success expression and progress, and <code>include_in_training: false</code>. It retains Caret&#39;s status in an extension field and maps statuses to the smaller record outcome vocabulary:</p><table tabindex="0"><thead><tr><th>Caret status</th><th>Record outcome</th></tr></thead><tbody><tr><td><code>success</code></td><td><code>success</code></td></tr><tr><td><code>partial</code>, <code>needs_user</code></td><td><code>partial</code></td></tr><tr><td><code>interrupted</code></td><td><code>abandoned</code></td></tr><tr><td>Other terminal statuses</td><td><code>failed</code></td></tr></tbody></table><p>The correction schema can represent rejected/chosen actions and segments, but this baseline has no automatic live correction writer. Likewise <code>source: shadow</code> and <code>source: teach</code> are schema values, not implemented continuous human-capture modes.</p><p><code>TaskRunner.wait</code> writes task records for eligible tasks with recording state. A resumed task may append another task summary; readers take the final line for its recording task ID. Observation-only tasks do not allocate recording state, and interruption paths that never reach the writer can leave step evidence without a final task record.</p><h2 id="privacy-and-retention-boundaries" tabindex="-1">Privacy and retention boundaries <a class="header-anchor" href="#privacy-and-retention-boundaries" aria-label="Permalink to “Privacy and retention boundaries”">​</a></h2><p>Secret tasks skip trajectory recording and screenshots. Recording also has a denylist and secure-field handling, but ordinary typed content and original action payloads can be sensitive: do not assume arbitrary values are redacted or encrypted. Export, remote processing and training need their own reviewed data policy.</p><p>Successful tasks delete screenshot artifacts from <code>vault/artifacts/&lt;trace&gt;</code>. Content-addressed screenshot blobs referenced by records have a separate lifetime; successful artifact cleanup is not blob garbage collection.</p><p>Optional <code>CARET_CU_RECALL=1</code> uses local finished-task recall to enrich new task cards. This is a separate retrieval feature, not automatic weight training. Full shadow/teach capture, the schema&#39;s predicate DAG pipeline and general encrypted sensitive-form handling remain proposals or unimplemented areas in this baseline.</p><h2 id="source-trail" tabindex="-1">Source trail <a class="header-anchor" href="#source-trail" aria-label="Permalink to “Source trail”">​</a></h2><p><a href="https://github.com/krishpop/caret/blob/57d53c0/src/record/logger.ts" target="_blank" rel="noreferrer">Recorder and action lifting</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/record/delta.ts" target="_blank" rel="noreferrer">Delta</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/record/blobs.ts" target="_blank" rel="noreferrer">Blob store</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/cu/task.ts" target="_blank" rel="noreferrer">Task writer</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/record/privacy.ts" target="_blank" rel="noreferrer">Privacy</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/cu/recall.ts" target="_blank" rel="noreferrer">Recall</a></p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};